<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/ai.php';$admin=require_admin($pdo);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
 if($op==='claim_status'){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'under_review');if(!in_array($status,['submitted','under_review','resolved','rejected','restricted'],true))throw new RuntimeException('Invalid status.');$note=trim((string)($_POST['note']??''));$pdo->prepare('UPDATE rights_claims SET status=?,moderator_note=?,resolved_at=IF(? IN (\'resolved\',\'rejected\',\'restricted\'),NOW(),NULL) WHERE id=?')->execute([$status,$note?:null,$status,$id]);$pdo->prepare("INSERT INTO moderation_actions(rights_claim_id,moderator_user_id,action_type,reason) VALUES(?,?,?,?)")->execute([$id,$admin['id'],'rights_claim_'.$status,$note?:null]);if($status==='restricted'){$pdo->prepare("UPDATE annotations a JOIN rights_claims rc ON rc.annotation_id=a.id SET a.status='restricted' WHERE rc.id=?")->execute([$id]);}$success='Rights claim updated.';}
 if($op==='report_status'){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'under_review');if(!in_array($status,['open','under_review','actioned','dismissed'],true))throw new RuntimeException('Invalid status.');$pdo->prepare('UPDATE moderation_reports SET status=?,resolved_at=IF(? IN (\'actioned\',\'dismissed\'),NOW(),NULL) WHERE id=?')->execute([$status,$status,$id]);$pdo->prepare('INSERT INTO moderation_actions(report_id,moderator_user_id,action_type,reason) VALUES(?,?,?,?)')->execute([$id,$admin['id'],'report_'.$status,trim((string)($_POST['note']??''))?:null]);$success='Report updated.';}
 if($op==='ai_claim'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT public_id FROM rights_claims WHERE id=?');$q->execute([$id]);$public=(string)$q->fetchColumn();$model=ai_setting_model_id($pdo,'moderation');if(!$public||!$model)throw new RuntimeException('Configure a moderation model first.');ai_queue_job($pdo,(int)$admin['id'],'moderation_rights_triage',$model,'rights_claim',$public,[],2);$success='AI rights triage queued.';}
 if($op==='ai_report'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT public_id FROM moderation_reports WHERE id=?');$q->execute([$id]);$public=(string)$q->fetchColumn();$model=ai_setting_model_id($pdo,'moderation');if(!$public||!$model)throw new RuntimeException('Configure a moderation model first.');ai_queue_job($pdo,(int)$admin['id'],'moderation_report_triage',$model,'moderation_report',$public,[],2);$success='AI moderation triage queued.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$claims=$pdo->query("SELECT rc.*,a.public_id annotation_public_id,s.canonical_url FROM rights_claims rc JOIN annotations a ON a.id=rc.annotation_id JOIN sources s ON s.id=a.source_id ORDER BY FIELD(rc.status,'submitted','under_review','restricted','resolved','rejected'),rc.created_at DESC LIMIT 100")->fetchAll();$reports=$pdo->query("SELECT * FROM moderation_reports ORDER BY FIELD(status,'open','under_review','actioned','dismissed'),created_at DESC LIMIT 100")->fetchAll();$runs=$pdo->query("SELECT task_type,scope_type,scope_public_id,output_text,status,created_at FROM ai_runs WHERE task_type LIKE 'moderation_%' ORDER BY created_at DESC LIMIT 20")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moderation · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/admin/">Annotated Admin</a><nav><a href="/admin/ai.php">AI</a><a href="/admin/source-monitor.php">Sources</a><a href="/admin/users.php">Users</a></nav></header><main class="panel"><div class="pageTitle"><span class="eyebrow">HUMAN REVIEW REQUIRED</span><h1>Moderation & rights</h1><p>AI triage is advisory only. It does not resolve claims, restrict content, or make legal determinations automatically.</p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><h2>Rights claims</h2><?php foreach($claims as $c):?><article class="card"><div class="meta"><?=h($c['status'])?> · <?=h($c['created_at'])?> · <?=h($c['claim_type'])?></div><h3>Claim <?=h($c['public_id'])?></h3><p><?=nl2br(h($c['description']))?></p><p><a href="/annotation.php?id=<?=h($c['annotation_public_id'])?>">Annotation</a> · <a href="<?=h($c['canonical_url'])?>" target="_blank" rel="noopener">Original source ↗</a></p><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="claim_status"><input type="hidden" name="id" value="<?=h((string)$c['id'])?>"><select name="status"><?php foreach(['submitted','under_review','resolved','rejected','restricted'] as $s):?><option <?=$c['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input name="note" placeholder="Moderator note" value="<?=h($c['moderator_note'])?>"><button>Save</button></form><form method="post" class="inlineActions"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="ai_claim"><input type="hidden" name="id" value="<?=h((string)$c['id'])?>"><button class="button secondary">AI triage</button></form></article><?php endforeach?><h2>Community reports</h2><?php foreach($reports as $r):?><article class="card"><div class="meta"><?=h($r['status'])?> · <?=h($r['created_at'])?> · <?=h($r['object_type'])?></div><h3><?=h($r['reason'])?></h3><p><?=nl2br(h($r['description']))?></p><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="report_status"><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><select name="status"><?php foreach(['open','under_review','actioned','dismissed'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input name="note" placeholder="Moderator note"><button>Save</button></form><form method="post" class="inlineActions"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="ai_report"><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><button class="button secondary">AI triage</button></form></article><?php endforeach?><h2>Recent AI triage</h2><?php foreach($runs as $r):?><div class="card"><div class="meta"><?=h($r['task_type'])?> · <?=h($r['scope_public_id'])?> · <?=h($r['status'])?></div><p><?=nl2br(h(mb_substr((string)$r['output_text'],0,4000)))?></p></div><?php endforeach?></main></body></html>
